import{_ as t,o as s,c as d,a6 as a}from"./chunks/framework.BrkgobfX.js";const k=JSON.parse('{"title":"会话管理","description":"会话记录的存储位置，resume、fork、archive、delete、queue 等子命令，以及相关斜杠命令与配置","frontmatter":{"title":"会话管理","description":"会话记录的存储位置，resume、fork、archive、delete、queue 等子命令，以及相关斜杠命令与配置","source":"https://daiw.org/manual/codex/sessions"},"headers":[],"relativePath":"manual/agent/codex/sessions.md","filePath":"manual/agent/codex/sessions.md"}'),i={name:"manual/agent/codex/sessions.md"};function o(n,e,c,r,l,h){return s(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="会话管理" tabindex="-1">会话管理 <a class="header-anchor" href="#会话管理" aria-label="Permalink to &quot;会话管理&quot;">​</a></h1><blockquote><p>会话记录的存储位置，resume、fork、archive、delete、queue 等子命令，以及相关斜杠命令与配置</p></blockquote><p>Codex 把每一次对话保存为一个会话（也称线程），用 UUID 标识，也可以用 <code>/rename</code> 起名字。大多数会话命令既接受 UUID，也接受会话名称；能解析为 UUID 时优先按 UUID 处理。</p><h2 id="会话存在哪里" tabindex="-1">会话存在哪里 <a class="header-anchor" href="#会话存在哪里" aria-label="Permalink to &quot;会话存在哪里&quot;">​</a></h2><p><code>$CODEX_HOME</code> 默认是 <code>~/.codex</code>。</p><table tabindex="0"><thead><tr><th>位置</th><th>内容</th></tr></thead><tbody><tr><td><code>$CODEX_HOME/sessions/YYYY/MM/DD/rollout-&lt;时间戳&gt;-&lt;会话ID&gt;.jsonl</code></td><td>每个会话的完整记录（rollout），恢复和派生都从这里读取</td></tr><tr><td><code>$CODEX_HOME/archived_sessions/</code></td><td>已归档会话的记录</td></tr><tr><td><code>$CODEX_HOME/history.jsonl</code></td><td>输入过的提示词，每行含 <code>session_id</code>、<code>ts</code>、<code>text</code>，供 <code>Up</code> 和 <code>Ctrl+R</code> 翻找</td></tr><tr><td>SQLite 状态库</td><td>会话列表元数据（<code>state_5.sqlite</code>）、分页线程历史（<code>thread_history_1.sqlite</code>）等运行时状态；目录由 <code>sqlite_home</code> 配置（优先）或 <code>CODEX_SQLITE_HOME</code> 环境变量指定，默认就是 <code>$CODEX_HOME</code></td></tr></tbody></table><p><code>codex exec --ephemeral</code> 不写会话记录，这类运行之后无法恢复。</p><h2 id="恢复会话-codex-resume" tabindex="-1">恢复会话 <code>codex resume</code> <a class="header-anchor" href="#恢复会话-codex-resume" aria-label="Permalink to &quot;恢复会话 `codex resume`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                          # 打开会话选择器，默认只列当前目录的交互式会话</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --last</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                   # 直接恢复当前目录最近的会话</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # 列出所有目录的会话，并显示 CWD 列</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0199a213-81c0-7800-8aa1-bbab2a035a53</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --last</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;接着把测试补上&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 恢复后立即发送一条消息</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>SESSION_ID</code></td><td>会话 UUID 或名称；省略时打开选择器</td></tr><tr><td><code>--last</code></td><td>跳过选择器，恢复当前目录近期的会话；此时首个位置参数被当作 <code>PROMPT</code></td></tr><tr><td><code>--all</code></td><td>不按当前目录过滤</td></tr><tr><td><code>--include-non-interactive</code></td><td>选择器和 <code>--last</code> 也纳入由 <code>codex exec</code>、app-server 创建的非交互会话</td></tr><tr><td><code>--remote &lt;ADDR&gt;</code>、<code>--remote-auth-token-env &lt;ENV_VAR&gt;</code></td><td>连接远程 app-server</td></tr><tr><td>其他</td><td>接受 <code>codex</code> 的全部交互参数（<code>-m</code>、<code>-s</code>、<code>-a</code>、<code>-C</code>、<code>--no-daemon</code> 等）和 <code>PROMPT</code></td></tr></tbody></table><p>按当前目录过滤时，会把同一仓库的主检出和其他托管 Git worktree 中对应的目录算进来（<code>worktrees</code> 自 v0.165.0 起已固化为常驻开启，不再需要功能开关）；v0.165.0 起会话选择器还支持按仓库筛选。v0.167.0 起，你可以在会话选择器里直接切换所连接的后端服务并保留输入框草稿；其他模型提供方下保存的对话也会继续显示，方便切回原提供方恢复，而无法直接恢复的旧对话则支持带可编辑提示词继续跟进。当前目录与会话保存的目录不同时，Codex 会询问使用哪一个。把 <code>tui.resume_cwd</code> 设为 <code>&quot;current&quot;</code> 或 <code>&quot;session&quot;</code> 可以固定选择、不再询问；显式的 <code>-C</code>/<code>--cd</code> 优先于该设置。</p><h2 id="派生会话-codex-fork" tabindex="-1">派生会话 <code>codex fork</code> <a class="header-anchor" href="#派生会话-codex-fork" aria-label="Permalink to &quot;派生会话 `codex fork`&quot;">​</a></h2><p>把一个已保存的会话复制成新会话（新 ID），原会话保持不变，适合从某个节点尝试另一种做法。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>SESSION_ID</code></td><td>要派生的会话 UUID 或名称；省略时打开选择器</td></tr><tr><td><code>--last</code></td><td>跳过选择器，派生当前目录近期的会话；此时首个位置参数被当作 <code>PROMPT</code></td></tr><tr><td><code>--all</code></td><td>不按当前目录过滤</td></tr><tr><td><code>--worktree</code></td><td>在新的 worktree 中运行派生出的会话，必须显式给出 <code>SESSION_ID</code></td></tr></tbody></table><p><code>codex fork</code> 同样接受交互参数，目录选择规则与 <code>codex resume</code> 相同。在会话内派生当前对话用 <code>/fork</code>（或在代理总览中对选中会话按 <code>f</code>，v0.161.0 起），非交互场景用 <code>codex exec fork</code>（见 <a href="/Front2Full/manual/agent/codex/exec">非交互模式</a>）。</p><h2 id="归档与删除" tabindex="-1">归档与删除 <a class="header-anchor" href="#归档与删除" aria-label="Permalink to &quot;归档与删除&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> archive</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SESSIO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">N</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # 从活跃列表中隐藏，记录保留</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unarchive</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SESSIO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">N</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # 恢复已归档的会话</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SESSIO</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">N</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">               # 永久删除，会先要求确认</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> delete</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">SESSION_UUI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --force</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 跳过确认，只接受 UUID</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><ul><li>按名称查找时，<code>archive</code> 只在活跃会话中找，<code>unarchive</code> 只在已归档会话中找，<code>delete</code> 两者都找；按名称只能匹配交互式会话，且同名会话不止一个时会报错；遇到这两种情况请改用 UUID。</li><li>v0.166.0 起，<code>unarchive</code> 在恢复父会话时会一并恢复随它归档的派生子代理线程。</li><li><code>delete</code> 不可撤销，由该会话派生的子代理线程会一并删除。确认步骤需要交互式终端，在脚本里只能用 <code>--force</code> 加 UUID。</li><li>这三个命令都接受 <code>--remote</code>、<code>--remote-auth-token-env</code>，以及 <code>-c</code>、<code>-p</code> 等配置参数；v0.156.0 起还可以在子命令之前加 <code>--no-daemon</code>（如 <code>codex --no-daemon archive &lt;SESSION&gt;</code>），不经过共享的后台服务直接操作（不能与 <code>--remote</code> 同用）。</li></ul><h2 id="给会话排队消息-codex-queue" tabindex="-1">给会话排队消息 <code>codex queue</code> <a class="header-anchor" href="#给会话排队消息-codex-queue" aria-label="Permalink to &quot;给会话排队消息 `codex queue`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --thread</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">会话ID或名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --message</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;完成后顺便更新 CHANGELOG&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> queue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --thread</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">会话ID或名</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">称</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --resume</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --message</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;先加载已保存会话再排队这条消息&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>--thread &lt;THREAD&gt;</code></td><td>会话 UUID 或精确的会话名称，只查找未归档的会话</td></tr><tr><td><code>--message &lt;TEXT&gt;</code></td><td>要排队的文本，不能为空；不支持图片</td></tr><tr><td><code>--resume</code></td><td>目标会话当前未加载在 app-server 内存中时，先从磁盘恢复该会话再把消息加入队列（v0.166.0 起）</td></tr></tbody></table><p>消息通过 app-server 的实验接口 <code>thread/queue/add</code> 加入该会话的队列，成功时打印 <code>Queued message &lt;ID&gt; for thread &lt;ID&gt;.</code>。命令会优先连接本机正在运行的 app-server 守护进程；带了配置覆盖参数而无法复用守护进程时会报错，此时去掉这些参数或改用 <code>--remote</code>。它必须经由共享服务写入，所以不接受 <code>--no-daemon</code>。官方文档没有收录这个子命令。</p><h2 id="浏览所有-agent-会话-codex-agents" tabindex="-1">浏览所有 agent 会话 <code>codex agents</code> <a class="header-anchor" href="#浏览所有-agent-会话-codex-agents" aria-label="Permalink to &quot;浏览所有 agent 会话 `codex agents`&quot;">​</a></h2><p>打开全部 agent 会话的总览（v0.156.0 起界面上称为 agent command center），与会话内的 <code>/agents</code> 相同。可用参数有 <code>--remote</code>、<code>--remote-auth-token-env</code>、<code>-C</code>/<code>--cd &lt;DIR&gt;</code>（在远程服务器上新建任务时使用的目录）、<code>--no-alt-screen</code>，以及 v0.167.0 起支持的 <code>--no-daemon</code>（在内嵌 app-server 模式下浏览本地会话，不再强制要求连接后台守护进程）。它不接受初始提示词或图片，workload identity 生效时不可用。在交互会话里，输入框为空时按 <code>←</code> 也能打开总览；v0.158.0 起，对话在另一个应用中打开、这里只能只读查看时，同样可以按 <code>←</code> 回到总览。总览支持直接隐藏、归档、永久删除、按 <code>f</code> 分叉（v0.161.0 起）或按 <code>p</code> 置顶（v0.162.0 起）任务，支持按状态筛选，按项目、目录（v0.165.0 起，将 worktree 归入所属仓库下）、状态或模型分组，并在后台任务产生新结果时显示未读标记（v0.167.0 起），详见<a href="/Front2Full/manual/agent/codex/subagents">子代理</a>。</p><h2 id="应用云端任务的改动-codex-apply" tabindex="-1">应用云端任务的改动 <code>codex apply</code> <a class="header-anchor" href="#应用云端任务的改动-codex-apply" aria-label="Permalink to &quot;应用云端任务的改动 `codex apply`&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apply</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">TASK_I</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 简写 codex a</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>取回 Codex Cloud 任务近期的 diff，用 <code>git apply</code> 应用到本地工作区；有冲突时以非零状态退出。云端任务的用法见 <a href="/Front2Full/manual/agent/codex/cloud-integrations">Codex Cloud、GitHub 与 IDE</a>。</p><h2 id="迁移旧会话-codex-migrate-rollouts" tabindex="-1">迁移旧会话 <code>codex migrate-rollouts</code> <a class="header-anchor" href="#迁移旧会话-codex-migrate-rollouts" aria-label="Permalink to &quot;迁移旧会话 `codex migrate-rollouts`&quot;">​</a></h2><p>检查旧版的本地会话，或者把它们迁移为分页的线程历史存储。默认只扫描并报告，不做任何修改。</p><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>--apply</code></td><td>真正执行迁移</td></tr><tr><td><code>--thread &lt;THREAD_ID&gt;</code></td><td>只处理指定的线程，可重复</td></tr><tr><td><code>--max-mib-per-second &lt;MIB&gt;</code></td><td>限制读写吞吐，单位 MiB/s，下限为 1</td></tr><tr><td><code>--json</code></td><td>输出完整的逐线程 JSON 报告</td></tr><tr><td><code>--verbose</code></td><td>每个会话打印一行结果</td></tr></tbody></table><p>有任一会话迁移失败时以非零状态退出。官方文档没有收录这个子命令。</p><p>新建的本地会话默认就使用分页线程历史，恢复旧会话时则沿用它原来的格式；在原会话里回退（空输入框中按两次 <code>Esc</code>）等功能只支持分页格式，旧格式的会话可以先用这个命令迁移。</p><h2 id="会话内的相关命令" tabindex="-1">会话内的相关命令 <a class="header-anchor" href="#会话内的相关命令" aria-label="Permalink to &quot;会话内的相关命令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>命令</th><th>作用</th></tr></thead><tbody><tr><td><code>/resume [ID或名称]</code></td><td>恢复已保存的会话；省略参数时打开选择器</td></tr><tr><td><code>/new [名称]</code>、<code>/clear [名称]</code></td><td>开始新对话；<code>/clear</code> 会先清屏</td></tr><tr><td><code>/fork [名称]</code></td><td>把当前对话派生为新对话</td></tr><tr><td><code>/rename [名称]</code></td><td>重命名当前会话</td></tr><tr><td><code>/archive</code>、<code>/delete</code></td><td>归档或永久删除当前会话（v0.162.0 起 <code>/archive</code> 在任务仍在运行时也可直接执行）。使用内嵌服务时两者完成后都会退出；连接本机守护进程或远程 app server 时改为回到代理总览（<code>/archive</code> 自 v0.155.0 起，<code>/delete</code> 自 v0.156.0 起）</td></tr><tr><td><code>/side [问题]</code></td><td>打开侧边对话（别名 <code>/btw</code>）；v0.163.0 起切换其他线程后再次执行 <code>/side</code>（不带参数）可回到刚才的侧边对话</td></tr><tr><td><code>/export [路径]</code></td><td>把对话导出为 Markdown</td></tr><tr><td><code>/agents</code></td><td>打开代理总览，查看、筛选并切换所有 agent 会话（v0.167.0 起在 <code>--no-daemon</code> 内嵌模式下也可用）</td></tr><tr><td>空输入框中按两次 <code>Esc</code></td><td>浏览之前的提示词，选中后把当前会话回退到那条提示词之前重新编辑；v0.156.0 起在原会话中回退，不再分叉出新会话，文件改动不会撤销。回退只支持分页历史格式的会话，旧格式会话会报错，可先用 <code>codex migrate-rollouts --apply</code> 迁移</td></tr></tbody></table><p>完整列表见 <a href="/Front2Full/manual/agent/codex/slash-commands">斜杠命令</a>。</p><h2 id="相关配置" tabindex="-1">相关配置 <a class="header-anchor" href="#相关配置" aria-label="Permalink to &quot;相关配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置项</th><th>说明</th></tr></thead><tbody><tr><td><code>history.persistence</code></td><td><code>save-all</code> 或 <code>none</code>，控制是否写入 <code>history.jsonl</code></td></tr><tr><td><code>history.max_bytes</code></td><td><code>history.jsonl</code> 的大小上限，超出时丢弃较早的条目</td></tr><tr><td><code>tui.resume_cwd</code></td><td>恢复或派生会话时使用的目录：<code>current</code> 或 <code>session</code>；未设置时询问</td></tr><tr><td><code>sqlite_home</code></td><td>SQLite 状态库所在的目录</td></tr></tbody></table><p>配置文件的写法见 <a href="/Front2Full/manual/agent/codex/configuration">配置文件 config.toml</a>，完整字段见 <a href="/Front2Full/manual/agent/codex/config-reference">配置项速查</a>。</p>',38)])])}const u=t(i,[["render",o]]);export{k as __pageData,u as default};
